def roman_to_int(roman: str) -> int:
    """Convert a well-formed uppercase Roman numeral to an integer."""
    values = {
        "I": 1,
        "V": 5,
        "X": 10,
        "L": 50,
        "C": 100,
        "D": 500,
        "M": 1000,
    }
    total = 0
    for index, letter in enumerate(roman):
