def balanced_brackets(text: str) -> bool:
    """Return whether the bracket characters in *text* are properly nested."""
    pairs = {')': '(', ']': '[', '}': '{'}
    openings = set(pairs.values())
    stack = []
    for char in text:
        if char in openings:
            stack.append(char)
        elif char in pairs:
            if not stack or stack.pop() != pairs[char]:
                return False
    return not stack

